before:
```react
const initialPlan = {name: "Survey", minutes: 10};
function extend(plan) {
  return {...plan, minutes: plan.minutes + 5};
}
function App() {
  const [plan, setPlan] = React.useState(initialPlan);
  return <main><p role="status">{plan.name}: {plan.minutes} minutes</p>
    <button onClick={() => setPlan(current => extend(current))}>Add five</button>
  </main>;
}
```
The first click shows Survey: 15 minutes; the second shows 20. initialPlan still contains 10.

```react
const initialPlan = {name: "Sketch", minutes: 0};
function extend(plan) {
  return {...plan, minutes: plan.minutes + 5};
}
function App() {
  const [plan, setPlan] = React.useState(initialPlan);
  return <main><p role="status">{plan.name}: {plan.minutes} minutes</p>
    <button onClick={() => setPlan(current => extend(current))}>Add five</button>
  </main>;
